SELECT (COUNT(DISTINCT ?month) AS ?count)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?obs sosa:madeBySensor ?sensor ;
         sosa:observedProperty ?prop ;
         sosa:resultTime ?time ;
         qudt:numericValue ?value .
    ?sensor rdfs:label "BW_CKS022" .
    ?prop rdfs:label "flow-normalized NO3N" .
    FILTER(?time >= "1997-01-01T00:00:00"^^xsd:dateTime && ?time < "1998-01-01T00:00:00"^^xsd:dateTime)
    FILTER(?value > 10.5)
    BIND(MONTH(?time) AS ?month)
  }
